D={
80187:("Horas fracionadas","**Quarter past** (e quinze), **half past** (e meia), **quarter to** (quinze para). *It's quarter past seven.* Em ponto: **o'clock**.",[("It's {{quarter past}} seven.","São sete e quinze."),("It's {{half past}} seven.","São sete e meia."),("It's {{quarter to}} eight.","Faltam quinze para as oito."),("It's seven {{o'clock}}.","São sete em ponto.")],"7:45 é…",["quarter to eight","quarter past seven","half past eight"],0,"Quarter to eight."),
80188:("What time does…?","Para horário de eventos: **What time does the movie start?** Com he/she/it: **does** + verbo sem -s. Resposta: **At seven.**",[("{{What time does}} the movie start?","A que horas começa o filme?"),("It starts {{at}} seven.","Começa às sete."),("{{What time does}} it end?","A que horas termina?"),("At nine.","Às nove.")],"Complete: “What time ___ the show start?”",["do","does","is"],1,"3ª pessoa: does."),
910023:("Read, write","**Read a book, write a message.** Também: **write an email, read the news.** *Write with a pen*, mas **text** como verbo: *I text my friend.*",[("I {{read}} a comic.","Leio um gibi."),("I {{write}} a message.","Escrevo uma mensagem."),("She {{texts}} her friend.","Ela manda mensagem à amiga."),("He writes with a fountain pen.","Ele escreve com caneta-tinteiro.")],"“Escrever uma mensagem”:",["write a message","read a message","do a message"],0,"write."),
80189:("Preparar o jantar","Para cozinhar: verbos no presente: **I cook, she stirs, he sets the table.** *Dinner is almost ready.* = quase pronto.",[("I {{cook}} soup.","Faço sopa."),("She {{stirs}} the pot.","Ela mexe a panela."),("He {{sets}} the table.","Ele põe a mesa."),("{{Dinner is almost ready}}.","O jantar está quase pronto.")],"“Quase pronto”:",["almost ready","all ready not","ready almost no"],0,"almost ready."),
80190:("Hora de dormir","Rotina da noite: **I put on my pajamas. She turns off the lamp. He says goodnight.** *Sweet dreams!* = bons sonhos.",[("I {{put on}} my pajamas.","Visto o pijama."),("She {{turns off}} the lamp.","Ela apaga a luz."),("He {{says}} goodnight.","Ele diz boa noite."),("{{Sweet dreams}}!","Bons sonhos!")],"O que se diz antes de dormir?",["Sweet dreams!","Good morning!","Welcome!"],0,"Sweet dreams."),
80191:("After, then","**After dinner, I wash the dishes. Then I read.** **After** + tempo; **then** = em seguida.",[("{{After}} dinner, I wash the dishes.","Depois do jantar, lavo a louça."),("{{Then}} I read a book.","Depois leio um livro."),("{{Then}} I drink tea.","Depois tomo chá."),("I relax on the sofa.","Relaxo no sofá.")],"“Depois do jantar”:",["after dinner","before dinner","then dinner"],0,"After = depois."),
80192:("Then","**Then** liga ações em ordem. *I shop, then I clean, then I cook.* Ocupado: **busy**.",[("I {{shop}}, {{then}} I clean.","Faço compras, depois limpo."),("{{Then}} I visit my aunt.","Depois visito minha tia."),("{{Then}} I cook dinner.","Depois faço o jantar."),("It's a busy Saturday!","É um sábado cheio!")],"Qual conector indica ordem?",["then","but","or"],0,"Then = depois."),
80193:("I don't…","Negativa no presente: **I / you / we / they + don't + verbo.** *I don't eat broccoli.* O verbo fica sem -s.",[("I {{don't eat}} broccoli.","Não como brócolis."),("We {{don't like}} fish.","Não gostamos de peixe."),("They {{don't have}} dessert.","Eles não têm sobremesa."),("I eat rice.","Eu como arroz.")],"Qual está certa?",["I don't eats meat.","I don't eat meat.","I no eat meat."],1,"don't + verbo base."),
80194:("He doesn't…","Negativa com **he/she/it**: **doesn't + verbo base.** *My cat doesn't like water.* O -s vai para o **doesn't**.",[("My cat {{doesn't like}} water.","Meu gato não gosta de água."),("She {{doesn't wear}} boots.","Ela não usa botas."),("It {{doesn't rain}} here.","Aqui não chove."),("He eats milk.","Ele toma leite.")],"Qual está certa?",["She doesn't likes tea.","She doesn't like tea.","She don't like tea."],1,"doesn't + verbo base."),
80195:("Do you…?","Perguntas no presente: **Do you play an instrument?** Resposta: **Yes, I do. / No, I don't.** Com **I / you / we / they**.",[("{{Do you play}} the guitar?","Você toca violão?"),("Yes, {{I do}}.","Sim."),("{{Do they play}} the piano?","Eles tocam piano?"),("No, {{they don't}}.","Não.")],"Resposta curta de sim:",["Yes, I do.","Yes, I play.","Yes, I'm."],0,"Yes, I do."),
80196:("Does she…?","Perguntas com **he/she/it**: **Does she work late?** Resposta: **Yes, she does. / No, she doesn't.** O verbo fica sem -s.",[("{{Does she work}} late?","Ela trabalha até tarde?"),("Yes, {{she does}}.","Sim."),("{{Does he take}} the bus?","Ele pega o ônibus?"),("No, {{he doesn't}}.","Não.")],"Qual está certa?",["Does she works?","Does she work?","Do she work?"],1,"does + verbo base."),
910024:("Cook dinner","Tarefas: **cook dinner, wash clothes, take out the trash, do the laundry.** Cuidado: **do the laundry**, **wash clothes**.",[("I {{cook dinner}}.","Faço o jantar."),("She {{washes clothes}}.","Ela lava roupa."),("He {{takes out the trash}}.","Ele leva o lixo para fora."),("We use detergent.","Usamos detergente.")],"“Levar o lixo para fora”:",["take out the trash","bring out garbage","do trash"],0,"take out the trash."),
80197:("Where do they live?","**Where do they live?** Resposta: **They live in a house.** Com *he/she*: **Where does he live?**",[("{{Where do they live}}?","Onde eles moram?"),("{{They live in}} a house.","Moram em uma casa."),("{{Where does he live}}?","Onde ele mora?"),("{{He lives in}} a village.","Mora em uma vila.")],"Complete: “Where ___ she live?”",["do","does","is"],1,"she → does."),
80198:("What does he do?","**What does he do for a living?** = qual é a profissão dele? Resposta: **He's a teacher.** *Does* porque é he/she.",[("{{What does he do}} for a living?","Qual é a profissão dele?"),("{{He's a}} teacher.","Ele é professor."),("{{She's a}} doctor.","Ela é médica."),("He drives a bus.","Ele dirige um ônibus.")],"Complete: “What ___ she do?”",["do","does","is"],1,"does."),
80199:("Why, because","**Why** pergunta o motivo; **because** responde. *Why is the sky blue? Because of the light.*",[("{{Why}} is the sky blue?","Por que o céu é azul?"),("{{Because}} of the sun.","Por causa do sol."),("{{Why}} is the sea blue?","Por que o mar é azul?"),("{{Because}} it reflects the sky.","Porque reflete o céu.")],"Para dar o motivo, use…",["because","why","so"],0,"Because = porque."),
80200:("By + transporte","Transporte: **by bus, by car, by train, by bike.** A pé: **on foot.** Pergunta: **How do you get to work?**",[("{{How do you get}} to work?","Como você vai ao trabalho?"),("I go {{by bus}}.","Vou de ônibus."),("She goes {{by bike}}.","Ela vai de bicicleta."),("He goes {{on foot}}.","Ele vai a pé.")],"“Vou de trem”:",["I go by train.","I go in train.","I go with train."],0,"by + meio."),
80201:("Who + verbo","**Who** como sujeito: **Who does the dishes?** — **I do.** *Who washes the floor?* Com who, o verbo vai com **-s**.",[("{{Who does}} the dishes?","Quem lava a louça?"),("{{I do}}.","Eu lavo."),("{{Who makes}} the bed?","Quem arruma a cama?"),("{{She does}}.","Ela arruma.")],"Complete: “Who ___ the trash?” (leva)",["take","takes","taking"],1,"Who + verbo-s."),
80202:("Which one?","**Which** é para escolher entre opções: **Which do you prefer, this or that?** Resposta: **I prefer this one.**",[("{{Which}} one do you prefer?","Qual você prefere?"),("{{I prefer}} this one.","Prefiro este."),("{{Both}} are nice.","Os dois são bonitos."),("I like that one too.","Gosto daquele também.")],"“Qual você prefere?”:",["Which do you prefer?","What you prefer one?","Who prefer?"],0,"Which + do you prefer?"),
80203:("Never, always, sometimes","**I'm never late.** Depois de **be**, o advérbio vem **depois**: *I'm always early.* Com verbo normal vai antes.",[("I'm {{never}} late.","Nunca me atraso."),("She is {{always}} early.","Ela sempre chega cedo."),("I {{sometimes}} run.","Às vezes corro."),("Sorry!","Desculpe!")],"Onde vai never com be?",["depois do be","antes do be","no fim"],0,"I'm never…"),
80204:("Hobbies","Hobbies: **My hobby is fishing. I collect stamps. I knit scarves.** **Hobby** = passatempo. *I like hiking.*",[("My {{hobby}} is {{fishing}}.","Meu passatempo é pescar."),("I {{collect}} stamps.","Colecione selos."),("She {{knits}} scarves.","Ela tricota cachecóis."),("We like hiking.","Gostamos de fazer trilhas.")],"“Meu passatempo é jardinagem”:",["My hobby is gardening.","My hobby are gardening.","My hobby gardening."],0,"is + hobby."),
910025:("Pick up, put down","**Pick up** = pegar. **Put down** = pôr no chão. **Drop** = deixar cair. **Throw away** = jogar fora. *Pick up the toys.*",[("{{Pick up}} the blocks.","Pegue os blocos."),("{{Put down}} the doll.","Pouse a boneca."),("Don't {{drop}} the marbles.","Não deixe cair as bolinhas."),("{{Throw away}} the trash.","Jogue o lixo fora.")],"“Jogar fora”:",["throw away","pick away","put up"],0,"throw away."),
80205:("I'd like…","Pedidos: **I'd like pancakes, please.** Em vez de *I want*: mais educado. Com várias coisas: **I'd like pancakes and juice.**",[("{{I'd like}} pancakes, please.","Gostaria de panquecas, por favor."),("With {{syrup}} and {{butter}}.","Com xarope e manteiga."),("And {{some}} juice.","E um pouco de suco."),("That's all, thanks.","É só, obrigado.")],"Mais educado:",["I'd like eggs.","I want eggs.","Give eggs."],0,"I'd like."),
80206:("A slice of, a scoop of","Medidas de comida: **a slice of cake, a scoop of ice cream.** *Cake* e *ice cream* não ganham -s com medida.",[("{{A slice of}} brownie.","Uma fatia de brownie."),("{{A scoop of}} vanilla.","Uma bola de baunilha."),("{{A cherry}} on top.","Uma cereja em cima."),("A cupcake, please.","Um cupcake, por favor.")],"“Uma bola de sorvete”:",["a scoop of ice cream","a ice cream scoop","one ice cream of"],0,"a scoop of."),
80208:("A little, a few","**A little** + incontável: *a little sugar.* **A few** + contável: *a few grapes.* Pense: dá para contar? → *few*.",[("{{A little}} sugar.","Um pouco de açúcar."),("{{A few}} grapes.","Algumas uvas."),("{{A few}} apples.","Algumas maçãs."),("{{A little}} lemon juice.","Um pouco de suco de limão.")],"Complete: “a ___ peaches”",["little","few","much"],1,"Contável: a few."),
80209:("Any e no","Em negativas: **any** (*We don't have any ketchup*) ou **no** (*We have no ketchup*). Com **no**, não use *don't*.",[("There {{isn't any}} ketchup.","Não há ketchup."),("There's {{no}} mustard.","Não há mostarda."),("Do we have {{any}} yogurt?","Temos iogurte?"),("We need lettuce.","Precisamos de alface.")],"Qual está certa?",["We don't have no milk.","We don't have any milk.","We have any milk."],1,"Don't + any."),
80210:("A jar of…","Embalagens: **a jar of jam, a roll of tape, a stick of butter, a loaf of bread.** **A ___ of** + substantivo.",[("{{A jar of}} jam.","Um pote de geleia."),("{{A roll of}} tape.","Um rolo de fita."),("{{A loaf of}} bread.","Um pão (inteiro)."),("{{A pinch of}} salt.","Uma pitada de sal.")],"“Um pote de mel”:",["a jar of honey","a honey jar of","a honey of jar"],0,"a jar of."),
80211:("Help yourself","Anfitrião: **Help yourself! Would you like some more?** Convidado: **No, thanks, I'm full.** *Delicious!*",[("{{Help yourself}}!","Fique à vontade!"),("{{Would you like some more}}?","Quer mais?"),("{{No, thanks, I'm full}}.","Não, obrigado, estou satisfeito."),("{{Delicious}}!","Delicioso!")],"Para convidar a se servir:",["Help yourself!","Take you!","You eat now!"],0,"Help yourself!"),
80212:("With, without","**With** = com. **Without** = sem. *A burger with cheese. A burger without onions.* Depois: **extra** = a mais.",[("A burger {{with}} cheese.","Um hambúrguer com queijo."),("{{Without}} onions, please.","Sem cebola, por favor."),("{{Extra}} cheese.","Queijo extra."),("No problem.","Sem problema.")],"“Sem cebola”:",["without onions","with no onions of","not onions with"],0,"without."),
910026:("Before, after, when","**Before** = antes de. **After** = depois de. **When** = quando. **While** = enquanto. *Wash your hands before eating.*",[("{{Before}} dinner, I cook.","Antes do jantar, cozinho."),("{{After}} dinner, I rest.","Depois do jantar, descanso."),("{{When}} I'm tired, I sleep.","Quando estou cansado, durmo."),("I read {{while}} I eat.","Leio enquanto como.")],"“Enquanto”:",["while","when","after"],0,"While = enquanto."),
80214:("Hot or iced?","Bebidas: **Hot or iced?** = quente ou gelada? Resposta: **Iced, please.** *Lemonade with ice.*",[("{{Hot or iced}}?","Quente ou gelado?"),("{{Iced}}, please.","Gelado, por favor."),("A cold juice.","Um suco gelado."),("Lemonade with ice.","Limonada com gelo.")],"“Quente” é…",["hot","iced","cold"],0,"Hot = quente."),
80215:("Yummy or yucky?","Opinião de comida: **yummy** = gostoso, **yucky** = nojento. Formal: **tasty / delicious**. *It's yummy!*",[("It's {{yummy}}!","Está gostoso!"),("It's {{yucky}}.","Está nojento."),("It's {{tasty}} and {{sweet}}.","É saboroso e doce."),("It's too spicy.","É picante demais.")],"Oposto de yummy:",["yucky","tasty","sweet"],0,"Yucky."),
80216:("Fresh from the farm","**Fresh** = fresco. **From the farm** = da fazenda. *Fresh eggs from the farm.* Adjetivo antes do nome.",[("{{Fresh}} eggs.","Ovos frescos."),("{{From the farm}}.","Da fazenda."),("{{Fresh}} milk from the cow.","Leite fresco da vaca."),("Local honey.","Mel local.")],"“Leite fresco”:",["fresh milk","milk fresh","milk of fresh"],0,"Adjetivo antes."),
}
